def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_o = opp[-1]
    last_m = me[-1]
    remaining = 100 - n

    if remaining <= 0:
        return 'D'
    if remaining == 1:
        return 'D'

    totalD = opp.count('D')
    d2 = opp[-2:].count('D')
    d3 = opp[-3:].count('D')
    d4 = opp[-4:].count('D')
    d5 = opp[-5:].count('D')
    d10 = opp[-10:].count('D')
    d20 = opp[-20:].count('D')

    severe = False
    if n <= 3 and totalD >= 2:
        severe = True
    elif d3 >= 3:
        severe = True
    elif d4 >= 3 and totalD >= 4:
        severe = True
    elif d5 >= 4 or d10 >= 6:
        severe = True
    elif n >= 20 and totalD * 2 >= n + 4:
        severe = True

    if last_o == 'D':
        if severe:
            return 'D'
        if last_m == 'D':
            return 'C'
        if n >= 2 and me[-2] == 'D':
            return 'C'
        return 'D'

    afterD_n = 0
    afterD_c = 0
    afterC_n = 0
    afterC_c = 0

    for i in range(n - 1):
        if me[i] == 'D':
            afterD_n += 1
            if opp[i + 1] == 'C':
                afterD_c += 1
        else:
            afterC_n += 1
            if opp[i + 1] == 'C':
                afterC_c += 1

    if severe:
        return 'D'

    if last_m == 'C':
        if totalD == 0 and n >= 22:
            return 'D'
    else:
        if totalD == 0 and afterD_n >= 1 and afterD_c == afterD_n and d20 == 0:
            return 'D'

    if last_m == 'C':
        if afterD_n >= 1 and afterD_c == afterD_n and d20 == 0:
            return 'D'
        if afterD_n >= 3 and afterD_c * 10 >= afterD_n * 9 and d20 <= 1:
            return 'D'
        if afterD_n >= 4 and afterC_n >= 4:
            pc = (afterC_c + 1.0) / (afterC_n + 2.0)
            pd = (afterD_c + 1.0) / (afterD_n + 2.0)
            if pd >= 0.75 and pc - pd <= 0.20:
                return 'D'
            if abs(pc - pd) <= 0.15 and pc <= 0.70:
                return 'D'
            if pc <= 0.45:
                return 'D'
        if n >= 30 and rng.random() < 0.015 and totalD <= 3 and d10 <= 1:
            return 'D'
        return 'C'

    if afterD_n >= 1 and afterD_c == afterD_n and d20 == 0:
        return 'D'
    if afterD_n >= 3 and afterD_c * 10 >= afterD_n * 9 and d20 <= 1:
        return 'D'
    if afterD_n >= 4 and afterC_n >= 4:
        pc = (afterC_c + 1.0) / (afterC_n + 2.0)
        pd = (afterD_c + 1.0) / (afterD_n + 2.0)
        if pd >= 0.75 and pc - pd <= 0.20:
            return 'D'
        if abs(pc - pd) <= 0.15 and pc <= 0.70:
            return 'D'
        if pc <= 0.45:
            return 'D'

    return 'C'
